/**
 * Check the assertion without a message.
 */
export function absoluteIsSmall(
  number: number
): boolean {
  let absolute = number;
  if (number < 0) {
    absolute = -number;
  }
  if (!(absolute >= 0)) {
    throw new Error(
      "Assertion failed: absolute >= 0"
    );
  }
  return absolute < 1000;
}

